exercises.starter:
#include <stdbool.h>
bool would_overflow(int a, int b) {
    return a + b < 0;
}

exercises.tests:
#include <assert.h>
#include <limits.h>
int main(void) {
    assert(!would_overflow(2, 3));
    assert(!would_overflow(-5, 2));
    assert(would_overflow(INT_MAX, 1));
    assert(would_overflow(INT_MIN, -1));
    assert(!would_overflow(INT_MAX, INT_MIN));
    return 0;
}
